'use strict';
/**
 * Config validation engine: checks a HAProxy or NGINX configuration against the official documentation of a
 * chosen version (knowledge bases in src/kb/*.json, regenerated by tools/kb) and adds version-aware recommendations.
 */
const V = require('./version');
const { analyzeHaproxy } = require('./haproxy');
const { analyzeNginx } = require('./nginx');
const haproxyKb = require('../kb/haproxy.json');
const nginxKb = require('../kb/nginx.json');

/** Versions the knowledge base knows, newest first, for the UI picker. */
function versions() {
  return {
    haproxy: { list: [...haproxyKb.versions].reverse(), latest: haproxyKb.versions[haproxyKb.versions.length - 1], generated: haproxyKb.generated, source: haproxyKb.source },
    nginx: { latest: nginxKb.latest, generated: nginxKb.generated, source: nginxKb.source },
  };
}

const SEV = { error: 0, warning: 1, info: 2 };

function summarize(findings) {
  const bySeverity = { error: 0, warning: 0, info: 0 };
  const byKind = { syntax: 0, compat: 0, recommendation: 0 };
  for (const f of findings) {
    bySeverity[f.severity] = (bySeverity[f.severity] || 0) + 1;
    if (f.category === 'syntax') byKind.syntax++; else if (f.category === 'recommendation' || /^rec-/.test(f.id) || f.category === 'performance' && /^rec-/.test(f.id)) byKind.recommendation++; else byKind.compat++;
  }
  return { total: findings.length, ...bySeverity, ...byKind, ok: bySeverity.error === 0 };
}

/**
 * @param {{product:'haproxy'|'nginx', version?:string, config?:string, files?:{name:string,content:string}[], build?:string}} opts
 */
function validateConfig(opts) {
  const product = opts.product;
  if (product !== 'haproxy' && product !== 'nginx') throw new Error(`Unknown product "${product}"`);
  const version = opts.version ? String(opts.version).slice(0, 64) : null;
  let r;
  if (product === 'haproxy') {
    const text = typeof opts.config === 'string' ? opts.config : (opts.files || []).map((f) => f.content).join('\n');
    r = analyzeHaproxy(text, { version: V.detect(version) || version });
  } else {
    const files = opts.files && opts.files.length ? opts.files : [{ name: 'nginx.conf', content: String(opts.config || '') }];
    r = analyzeNginx(files, { version: V.detect(version) || version, build: opts.build, notes: [] });
  }
  const findings = r.findings.sort((a, b) => SEV[a.severity] - SEV[b.severity] || (a.line || 0) - (b.line || 0));
  return { product, target: r.target, kb: r.kb, summary: summarize(findings), findings };
}

module.exports = { validateConfig, versions, summarize, analyzeHaproxy, analyzeNginx };
